import douala from "../../assets/routes/douala.jpg";
import yaounde from "../../assets/routes/yaounde.jpg";
import kribi from "../../assets/routes/kribi.jpg";
import buea from "../../assets/routes/buea.jpg";
import React from "react";
import "./Routes.css";

import Navbar from "../../components/Navbar/Navbar";
import Footer from "../../components/Footer/Footer";

function Routes() {

const routes = [

{
from:"Douala",
to:"Yaoundé",
price:"5,000",
duration:"5 Hours",
type:"VIP"
},

{
from:"Bamenda",
to:"Douala",
price:"7,000",
duration:"7 Hours",
type:"Standard"
},

{
from:"Buea",
to:"Limbe",
price:"2,000",
duration:"1 Hour",
type:"Shuttle"
},

{
from:"Yaoundé",
to:"Kribi",
price:"4,500",
duration:"4 Hours",
type:"VIP"
}

];

return (

<>

<Navbar/>

<section className="routes-page">

<h1>Available Routes</h1>

<p>
Choose from our available destinations.
</p>

<input
type="text"
placeholder="Search destination..."
className="search-route"
/>

<div className="route-container">

{
routes.map((route,index)=>(

<div className="route-card" key={index}>

<div>

<h3>
{route.from} → {route.to}
</h3>

<span>{route.duration}</span>

<p>{route.type}</p>

</div>

<div>

<h2>
XAF {route.price}
</h2>

<button>
Book Now
</button>

</div>

</div>

))
}

</div>

</section>

<Footer/>

</>

);

}

export default Routes;
